insert into passages (id, text, difficulty_level, b, active) values
('8f0002b3-025b-4163-a195-b62d4c46d5cd', 'Recycling programs have become common in cities around the world, but their effectiveness varies widely depending on how they are implemented. In some cities, residents are required to sort their waste into several categories, such as paper, glass, plastic, and organic material, before it is collected. Studies show that this kind of detailed sorting system tends to produce cleaner, more usable recycled materials than programs where everything is placed into a single bin. However, detailed sorting systems also require more effort from residents, and cities that adopt them often see lower participation rates, at least initially. To address this problem, some municipalities have started offering financial incentives, such as reduced waste collection fees for households that recycle consistently. Officials in these cities report that participation tends to increase once residents understand both the environmental benefits and the personal financial savings involved.', 2, -1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('3bd584a6-c7be-45c1-8e68-9d3b9e8f157c', 'sentence_completion', 'By the time we arrived at the theater, the movie ___ already started.', NULL, '[{"id": "a", "text": "had"}, {"id": "d", "text": "has"}, {"id": "b", "text": "was"}, {"id": "c", "text": "have"}]'::jsonb, 0, '{"strategy": "By the time we arrived...already = בזמן שהגענו...כבר. פעולה שהושלמה לפני פעולה אחרת בעבר = past perfect.", "correct_reason": "had = כבר. had + started מציין פעולה שהושלמה לפני פעולה אחרת בעבר.", "options_analysis": ["נכון! had + started = past perfect, מציין פעולה שהושלמה לפני עבר אחר", "has = הווה מושלם — לא מתאים לעבר", "was לבד לא מתאים לפני ''already started''", "have = הווה מושלם רבים — לא מתאים לעבר"]}', 1.07, -1.0, 0.25, 2, 'ai', NULL, true),
('23d0023a-e7e3-4529-9b41-b2d81e6d1ced', 'sentence_completion', 'Neither of the students ___ finished the assignment yet.', NULL, '[{"id": "d", "text": "had"}, {"id": "a", "text": "has"}, {"id": "c", "text": "having"}, {"id": "b", "text": "have"}]'::jsonb, 1, '{"strategy": "Neither of the students = אף אחד מהתלמידים. neither נחשב יחיד דקדוקית.", "correct_reason": "has = יש לו. neither + of + רבים עדיין מקבל פועל ביחיד.", "options_analysis": ["had מתאים לעבר, לא ל-yet שמרמז הווה מושלם", "נכון! neither = יחיד דקדוקית, מקבל has", "ing לא מתאים אחרי neither", "have = רבים — neither דורש יחיד למרות ה-of the students"]}', 0.93, -1.0, 0.25, 2, 'ai', NULL, true),
('9b933eea-23ba-4f3d-bf7e-fe8329c57061', 'sentence_completion', 'The report ___ by the manager before it is sent to the client.', NULL, '[{"id": "b", "text": "reviewed"}, {"id": "d", "text": "is reviewed"}, {"id": "c", "text": "will be reviewed"}, {"id": "a", "text": "reviews"}]'::jsonb, 2, '{"strategy": "before it is sent = לפני שהוא נשלח. פעולה עתידית בקול סביל.", "correct_reason": "will be reviewed = ייבדק. עתיד + סביל: will be + participle.", "options_analysis": ["עבר — לא מתאים ל''before it is sent'' שמרמז עתיד", "הווה סביל — לא מתאים לתהליך עתידי", "נכון! will be + participle = עתיד סביל", "הווה פשוט פעיל — לא מתאים לסביל עתידי"]}', 0.82, -1.0, 0.25, 2, 'ai', NULL, true),
('0cdad6d6-3bda-4c79-b67a-e098ba5fe6be', 'sentence_completion', 'If I ___ more time, I would learn to play the piano.', NULL, '[{"id": "a", "text": "have"}, {"id": "b", "text": "will have"}, {"id": "c", "text": "has"}, {"id": "d", "text": "had"}]'::jsonb, 3, '{"strategy": "would learn = תבנית תנאי סוג שני (היפותטי בהווה).", "correct_reason": "had = היה לי. תנאי סוג 2: if + past simple, would + base verb.", "options_analysis": ["have = הווה — לא מתאים לתנאי סוג 2", "will have = עתיד — לא מתאים לתנאי היפותטי", "has = הווה גוף שלישי — לא מתאים לתנאי סוג 2", "נכון! if + had (past simple) + would = תנאי סוג 2"]}', 0.76, -1.0, 0.25, 2, 'ai', NULL, true),
('d42c4ee8-bde1-4c59-89f4-885e3e371009', 'sentence_completion', 'The book, ___ was written in 1990, is still popular today.', NULL, '[{"id": "a", "text": "which"}, {"id": "c", "text": "whose"}, {"id": "b", "text": "when"}, {"id": "d", "text": "who"}]'::jsonb, 0, '{"strategy": "the book...is still popular = הספר...עדיין פופולרי. פסוקית זיקה על עצם (the book), לא אדם.", "correct_reason": "which = ש-. which משמש לעצמים, לא לאנשים.", "options_analysis": ["נכון! which = מתאים לעצם דומם כמו book", "whose מציין שייכות, לא מתאים כאן", "when מציין זמן, לא מתאים לתיאור עצם", "who משמש לאנשים, לא לעצמים כמו book"]}', 1.06, -1.0, 0.25, 2, 'ai', NULL, true),
('13b1a260-db67-4014-8b91-d279c8e4ec0b', 'sentence_completion', 'She suggested that he ___ a doctor immediately.', NULL, '[{"id": "b", "text": "sees"}, {"id": "d", "text": "see"}, {"id": "a", "text": "saw"}, {"id": "c", "text": "seeing"}]'::jsonb, 1, '{"strategy": "suggested that = הציע ש-. אחרי verbs of suggestion בא subjunctive (צורת בסיס).", "correct_reason": "see = לראות. suggest + that + subject + base form (subjunctive).", "options_analysis": ["sees = מקבל s — לא מתאים ל-subjunctive אחרי suggest", "נכון! subjunctive: suggest that + subject + base form", "עבר לא מתאים לתבנית subjunctive", "ing לא מתאים אחרי that + subject"]}', 1.01, -1.0, 0.25, 2, 'ai', NULL, true),
('18c496c5-b7f8-47f5-92e4-2a3bb49e446a', 'sentence_completion', 'Not only ___ the exam, but she also received the highest score in the class.', NULL, '[{"id": "a", "text": "she did pass"}, {"id": "c", "text": "passed she"}, {"id": "b", "text": "did she pass"}, {"id": "d", "text": "she passed"}]'::jsonb, 2, '{"strategy": "Not only...but also = לא רק...אלא גם. Not only בתחילת משפט דורש היפוך (inversion).", "correct_reason": "did she pass = עברה. Not only + auxiliary + subject + verb = היפוך תקני.", "options_analysis": ["סדר מילים שגוי — צריך auxiliary לפני subject", "סדר מילים שגוי לגמרי", "נכון! Not only + did + subject + base verb = היפוך תקני", "חסר היפוך אחרי Not only בתחילת המשפט"]}', 1.08, -1.0, 0.25, 2, 'ai', NULL, true),
('be6adcd3-fdd8-4a7c-9100-9e884ae063a9', 'sentence_completion', 'The number of students in the class ___ increased significantly this year.', NULL, '[{"id": "c", "text": "having"}, {"id": "a", "text": "have"}, {"id": "d", "text": "were"}, {"id": "b", "text": "has"}]'::jsonb, 3, '{"strategy": "The number of = המספר של. ''the number of'' דקדוקית נחשב יחיד (בניגוד ל-''a number of'').", "correct_reason": "has = יש. ''the number of'' + פועל ביחיד.", "options_analysis": ["ing לא תקין ללא עזר", "have = רבים — לא מתאים ל''the number of'' שהוא יחיד", "were = עבר רבים — לא מתאים ל''this year'' ול-''the number of''", "נכון! ''the number of'' = יחיד דקדוקית, מקבל has"]}', 0.79, -1.0, 0.25, 2, 'ai', NULL, true),
('a617bbe9-a40d-4b18-bd2a-ac842e732f2b', 'sentence_completion', 'Hardly ___ the meeting begun when the fire alarm went off.', NULL, '[{"id": "a", "text": "had"}, {"id": "d", "text": "has"}, {"id": "b", "text": "did"}, {"id": "c", "text": "was"}]'::jsonb, 0, '{"strategy": "Hardly...when = בקושי...כש-. Hardly + past perfect + when מציין רצף אירועים מהיר.", "correct_reason": "had = כבר. Hardly had + past participle + when = תבנית תקנית.", "options_analysis": ["נכון! Hardly had + participle + when = תבנית תקנית לרצף מהיר", "has לא מתאים לעבר — ''went off'' מרמז עבר", "did לא מתאים לתבנית Hardly...when", "was לא מתאים ל-begun שדורש had"]}', 0.9, -1.0, 0.25, 2, 'ai', NULL, true),
('57d23134-2021-4a41-996e-e33f5f61b309', 'sentence_completion', 'The committee is considering ___ the new policy next month.', NULL, '[{"id": "c", "text": "implemented"}, {"id": "a", "text": "implementing"}, {"id": "d", "text": "implement"}, {"id": "b", "text": "to implement"}]'::jsonb, 1, '{"strategy": "considering = שוקל. consider נדרש gerund (ing form) כמושא.", "correct_reason": "implementing = ליישם. consider + gerund הוא תבנית תקנית.", "options_analysis": ["implemented = עבר — לא תקין כמושא ל-considering", "נכון! consider + gerund (ing) = תבנית תקנית", "implement לבד לא תקין אחרי considering", "to implement = infinitive — consider לא לוקח infinitive"]}', 1.09, -1.0, 0.25, 2, 'ai', NULL, true),
('0664a5ce-4040-4dff-8222-9e71d0d68e08', 'sentence_completion', 'Despite ___ hard, he failed to pass the exam.', NULL, '[{"id": "a", "text": "studied"}, {"id": "b", "text": "study"}, {"id": "d", "text": "studying"}, {"id": "c", "text": "to study"}]'::jsonb, 2, '{"strategy": "Despite = למרות. אחרי despite בא gerund (ing) או שם עצם, לא infinitive.", "correct_reason": "studying = ללמוד. despite + gerund הוא תבנית תקנית.", "options_analysis": ["studied = עבר — לא תקין אחרי despite", "study לבד ללא ing לא תקין אחרי despite", "נכון! despite + gerund (ing) = תבנית תקנית", "to study = infinitive — despite לא לוקח infinitive"]}', 1.15, -1.0, 0.25, 2, 'ai', NULL, true),
('41eb8211-546f-4753-8921-a4bd1bbb3cd7', 'sentence_completion', 'The more you practice, ___ you will become at playing the guitar.', NULL, '[{"id": "a", "text": "good"}, {"id": "c", "text": "best"}, {"id": "d", "text": "better"}, {"id": "b", "text": "the better"}]'::jsonb, 3, '{"strategy": "The more...the better = ככל ש...כך יותר. תבנית השוואה כפולה (the + comparative, the + comparative).", "correct_reason": "the better = כך יותר טוב. תבנית ''the more..., the better...'' דורשת the לפני שני החלקים.", "options_analysis": ["good = צורת יסוד — לא מתאים לתבנית השוואה כפולה", "best = עילית — לא מתאים לתבנית ''the more, the better''", "better לבד ללא the — חסר the הנדרש בתבנית", "נכון! ''the more..., the better'' = תבנית השוואה כפולה תקנית"]}', 0.76, -1.0, 0.25, 2, 'ai', NULL, true),
('cb66f934-a2d0-4c6a-8195-f81f88f71524', 'restatement', 'Although she was tired, she finished the marathon.', NULL, '[{"id": "c", "text": "She finished the marathon even though she felt tired."}, {"id": "a", "text": "She refused to run the marathon at all."}, {"id": "b", "text": "She was not tired when she finished the marathon."}, {"id": "d", "text": "She did not finish the marathon because she was tired."}]'::jsonb, 0, '{"strategy": "Although...tired, finished = למרות עייפות, סיימה. ניגוד.", "correct_reason": "אותה משמעות בדיוק: סיימה את המרתון למרות התשישות.", "options_analysis": ["נכון! אותה משמעות בדיוק: סיימה למרות העייפות", "סותר את קיום המרתון וסיומו", "סותר ''she was tired''", "הפוך — סותר ''finished the marathon''"]}', 0.9, -1.0, 0.25, 2, 'ai', NULL, true),
('6e8ba3f4-6c95-4d4a-bf41-a1e6949688ce', 'restatement', 'The teacher explained the lesson so clearly that all the students understood it.', NULL, '[{"id": "a", "text": "No students understood the lesson at all."}, {"id": "b", "text": "The teacher''s explanation was so clear that every student understood the lesson."}, {"id": "d", "text": "The lesson was too confusing for anyone to understand."}, {"id": "c", "text": "The teacher refused to explain the lesson."}]'::jsonb, 1, '{"strategy": "so clearly that all understood = כל כך ברור שכולם הבינו. תוצאה.", "correct_reason": "אותה משמעות בדיוק: ההסבר היה כה ברור שכל תלמיד הבין.", "options_analysis": ["הפוך — סותר ''all the students understood it''", "נכון! אותה משמעות בדיוק: הסבר ברור שכל תלמיד הבין", "הפוך — סותר ''so clearly that all the students understood it''", "סותר את קיום ההסבר עצמו"]}', 0.98, -1.0, 0.25, 2, 'ai', NULL, true),
('36e7dd81-986c-4428-8e33-178ce8ee9d59', 'restatement', 'Unless you study harder, you will not pass the test.', NULL, '[{"id": "b", "text": "You have already passed the test."}, {"id": "c", "text": "You will pass the test even without studying."}, {"id": "d", "text": "If you don''t study harder, you will fail the test."}, {"id": "a", "text": "Studying harder will make you fail the test."}]'::jsonb, 2, '{"strategy": "Unless = אלא אם. Unless X, not Y = If not X, not Y.", "correct_reason": "אותה משמעות בדיוק: אם לא תלמד יותר קשה, תיכשל.", "options_analysis": ["סותר את המשפט כולו שמרמז שהמבחן עוד לא נערך", "הפוך — סותר ''you will not pass''", "נכון! אותה משמעות בדיוק: Unless = אם לא", "הפוך — לימוד קשה יותר אמור לעזור, לא לגרום לכישלון"]}', 1.04, -1.0, 0.25, 2, 'ai', NULL, true),
('11ac6826-017f-41dd-afe8-ec474b653355', 'restatement', 'The concert was canceled due to the severe weather conditions.', NULL, '[{"id": "b", "text": "The concert was canceled for no particular reason."}, {"id": "d", "text": "The concert took place despite the bad weather."}, {"id": "a", "text": "The weather was perfect for the concert."}, {"id": "c", "text": "Bad weather caused the concert to be canceled."}]'::jsonb, 3, '{"strategy": "canceled due to = בוטל בגלל. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק: מזג האוויר הקשה גרם לביטול.", "options_analysis": ["סותר ''due to the severe weather conditions'' — כן הייתה סיבה ספציפית", "הפוך — סותר ''was canceled''", "הפוך — ''perfect'' סותר ''severe weather conditions''", "נכון! אותה משמעות בדיוק: מזג אוויר קשה גרם לביטול"]}', 0.93, -1.0, 0.25, 2, 'ai', NULL, true),
('a422925d-f4c0-44b8-89b1-e55c67de7fe1', 'restatement', 'As soon as the rain stopped, the children went outside to play.', NULL, '[{"id": "c", "text": "The children went outside immediately after the rain ended."}, {"id": "b", "text": "The children stayed inside even after the rain stopped."}, {"id": "a", "text": "The children waited a long time after the rain stopped before going outside."}, {"id": "d", "text": "It never stopped raining that day."}]'::jsonb, 0, '{"strategy": "As soon as = ברגע ש-. פעולה מיידית אחרי אירוע.", "correct_reason": "אותה משמעות בדיוק: הילדים יצאו מיד אחרי שהגשם נגמר.", "options_analysis": ["נכון! אותה משמעות בדיוק: יצאו מיד אחרי שהגשם נגמר", "הפוך — סותר ''went outside to play''", "סותר ''as soon as'' שמרמז על מיידיות", "סותר ''the rain stopped''"]}', 1.07, -1.0, 0.25, 2, 'ai', NULL, true),
('4a9769e3-2c9b-402d-b543-28f9f7f8d51e', 'restatement', 'The company hired more employees in order to meet the growing demand.', NULL, '[{"id": "b", "text": "The company did not hire anyone despite growing demand."}, {"id": "c", "text": "The company hired more employees because demand was growing."}, {"id": "a", "text": "The company fired employees due to decreasing demand."}, {"id": "d", "text": "Demand for the company''s products was declining."}]'::jsonb, 1, '{"strategy": "in order to meet growing demand = כדי לענות על ביקוש גדל. מטרה-סיבה.", "correct_reason": "אותה משמעות בדיוק: החברה שכרה עובדים כי הביקוש גדל.", "options_analysis": ["סותר ''hired more employees''", "נכון! אותה משמעות בדיוק: שכרה עובדים כי הביקוש גדל", "הפוך — ''fired'' סותר ''hired'', ''decreasing'' סותר ''growing''", "הפוך — ''declining'' סותר ''growing demand''"]}', 1.02, -1.0, 0.25, 2, 'ai', NULL, true),
('b904e02f-ca39-4d33-99a6-6da0b11787ef', 'restatement', 'Even though the flight was delayed by three hours, we still made our connection.', NULL, '[{"id": "a", "text": "We missed our connection because of the flight delay."}, {"id": "d", "text": "We decided not to take the connecting flight."}, {"id": "b", "text": "We made our connecting flight despite the three-hour delay."}, {"id": "c", "text": "The flight was not delayed at all."}]'::jsonb, 2, '{"strategy": "Even though...delayed...still made = למרות עיכוב...עדיין הצלחנו. ניגוד.", "correct_reason": "אותה משמעות בדיוק: הצלחנו לתפוס את ההמשך למרות עיכוב של שלוש שעות.", "options_analysis": ["הפוך — סותר ''we still made our connection''", "סותר ''we still made our connection''", "נכון! אותה משמעות בדיוק: הצלחנו למרות העיכוב", "סותר ''delayed by three hours''"]}', 1.02, -1.0, 0.25, 2, 'ai', NULL, true),
('3c1142ea-d13f-4959-8842-55210d904c8d', 'restatement', 'The article was written in such a complicated way that few readers finished it.', NULL, '[{"id": "c", "text": "Everyone who started the article finished it easily."}, {"id": "a", "text": "No one started reading the article."}, {"id": "b", "text": "The article was extremely simple to read."}, {"id": "d", "text": "The article was so complex that only a small number of readers finished reading it."}]'::jsonb, 3, '{"strategy": "so complicated that few finished = כה מסובך שמעטים סיימו. תוצאה.", "correct_reason": "אותה משמעות בדיוק: כה מורכב שרק מספר קטן של קוראים סיימו.", "options_analysis": ["הפוך — סותר ''few readers finished it''", "סותר את קיום קוראים שכן ניגשו למאמר", "הפוך — ''simple'' סותר ''complicated''", "נכון! אותה משמעות בדיוק: מורכב, רק מעטים סיימו"]}', 0.82, -1.0, 0.25, 2, 'ai', NULL, true),
('8de93940-dd39-4824-90d1-7505905ff39d', 'restatement', 'The bridge was closed for repairs, forcing drivers to take a longer route.', NULL, '[{"id": "d", "text": "Drivers had to use a longer route because the bridge was closed for repairs."}, {"id": "b", "text": "The bridge did not need any repairs."}, {"id": "c", "text": "The bridge remained open throughout the repairs."}, {"id": "a", "text": "Drivers took a shorter route because of the repairs."}]'::jsonb, 0, '{"strategy": "closed for repairs, forcing = נסגר לתיקונים, מה שהכריח. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק: נהגים נאלצו לנקוט מסלול ארוך יותר בגלל סגירת הגשר.", "options_analysis": ["נכון! אותה משמעות בדיוק: מסלול ארוך יותר בגלל סגירת הגשר", "סותר ''closed for repairs'' — כן היה צורך בתיקונים", "הפוך — סותר ''was closed for repairs''", "הפוך — ''shorter route'' סותר ''longer route''"]}', 0.97, -1.0, 0.25, 2, 'ai', NULL, true),
('578b6f9d-b092-4ee1-9fed-8280742aaa97', 'restatement', 'Having finished her homework, Sarah went to bed early.', NULL, '[{"id": "a", "text": "Sarah went to bed before finishing her homework."}, {"id": "b", "text": "Sarah went to bed early after she finished her homework."}, {"id": "c", "text": "Sarah stayed up late doing homework."}, {"id": "d", "text": "Sarah never finished her homework."}]'::jsonb, 1, '{"strategy": "Having finished...went = אחרי שסיימה...הלכה. רצף פעולות.", "correct_reason": "אותה משמעות בדיוק: שרה הלכה לישון מוקדם אחרי שסיימה שיעורי בית.", "options_analysis": ["הפוך — סותר ''having finished her homework''", "נכון! אותה משמעות בדיוק: הלכה לישון אחרי שסיימה", "סותר ''went to bed early''", "הפוך — סותר ''having finished''"]}', 0.89, -1.0, 0.25, 2, 'ai', NULL, true),
('e004d4aa-7144-4645-b3ac-455667445df5', 'restatement', 'The new law, though controversial, was passed by a narrow margin.', NULL, '[{"id": "a", "text": "The law was rejected because it was too controversial."}, {"id": "c", "text": "No vote was ever held on the law."}, {"id": "d", "text": "Despite being controversial, the law was approved by a small margin."}, {"id": "b", "text": "The law was passed unanimously with no controversy."}]'::jsonb, 2, '{"strategy": "though controversial, passed = למרות מחלוקת, עבר. ניגוד.", "correct_reason": "אותה משמעות בדיוק: למרות המחלוקת, החוק אושר ברוב קטן.", "options_analysis": ["הפוך — סותר ''was passed''", "סותר ''was passed by a narrow margin''", "נכון! אותה משמעות בדיוק: למרות המחלוקת, אושר ברוב קטן", "הפוך — ''unanimously'' סותר ''narrow margin'' ו''controversial''"]}', 0.78, -1.0, 0.25, 2, 'ai', NULL, true),
('d27cd619-9e65-489b-9c05-53cf1c9164a1', 'restatement', 'The workers went on strike because their demands for higher wages were ignored.', NULL, '[{"id": "d", "text": "The workers never asked for higher wages."}, {"id": "c", "text": "The workers received a raise without needing to strike."}, {"id": "a", "text": "The workers'' demands for higher wages were met immediately."}, {"id": "b", "text": "The workers went on strike as a result of their wage demands being ignored."}]'::jsonb, 3, '{"strategy": "went on strike because...ignored = שבתו כי...התעלמו. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק: העובדים שבתו כתוצאה מהתעלמות מדרישותיהם.", "options_analysis": ["סותר ''their demands for higher wages''", "הפוך — סותר ''went on strike''", "הפוך — סותר ''were ignored''", "נכון! אותה משמעות בדיוק: שבתו כתוצאה מהתעלמות מהדרישות"]}', 0.77, -1.0, 0.25, 2, 'ai', NULL, true),
('83c1f087-124b-4fe6-a019-266b2f5a47dc', 'reading_comprehension', 'What is the main topic of the passage?', '8f0002b3-025b-4163-a195-b62d4c46d5cd', '[{"id": "c", "text": "The effectiveness of different recycling program designs"}, {"id": "d", "text": "How to build a recycling factory"}, {"id": "b", "text": "Why plastic is harmful to the environment"}, {"id": "a", "text": "The history of recycling programs"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה משווה בין סוגי תוכניות מיחזור ויעילותן.", "correct_reason": "כל הפסקה עוסקת בהשוואה בין שיטות מיחזור שונות ויעילותן.", "options_analysis": ["נכון! השוואת יעילות תוכניות מיחזור = הנושא המרכזי", "לא מוזכר בפסקה כלל", "לא מוזכר בפסקה כלל", "לא מוזכר בפסקה כלל"]}', 0.8, -1.0, 0.25, 2, 'ai', NULL, true),
('d7e43915-8d1f-4cb5-9aa8-ecfbd6866493', 'reading_comprehension', 'According to the passage, what tends to happen when cities require detailed waste sorting?', '8f0002b3-025b-4163-a195-b62d4c46d5cd', '[{"id": "a", "text": "Participation rates always increase immediately"}, {"id": "d", "text": "The recycled materials tend to be cleaner and more usable, but participation may initially be lower"}, {"id": "c", "text": "Residents are no longer required to recycle at all"}, {"id": "b", "text": "Recycling becomes completely ineffective"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את התוצאה של מיון מפורט בפסקה.", "correct_reason": "הפסקה אומרת: ''this kind of detailed sorting system tends to produce cleaner, more usable recycled materials...cities that adopt them often see lower participation rates''.", "options_analysis": ["הפוך — הפסקה אומרת שההשתתפות עלולה לרדת בהתחלה, לא לעלות מיד", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה כלל", "הפוך גמור מהמסקנה בפסקה"]}', 0.86, -1.0, 0.25, 2, 'ai', NULL, true),
('9056f472-be49-4637-934f-98da51b169cc', 'reading_comprehension', 'The word "municipalities" in the passage most closely means:', '8f0002b3-025b-4163-a195-b62d4c46d5cd', '[{"id": "b", "text": "environmental organizations"}, {"id": "a", "text": "private companies"}, {"id": "d", "text": "local city governments"}, {"id": "c", "text": "individual citizens"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''some municipalities have started offering financial incentives''.", "correct_reason": "municipalities = רשויות עירוניות/מוניציפליות.", "options_analysis": ["לא נאמר בפסקה כלל", "לא נאמר בפסקה — אין אזכור לחברות פרטיות", "נכון! municipalities = רשויות עירוניות מקומיות", "לא מדויק — מדובר ברשויות, לא באזרחים בודדים"]}', 1.05, -1.0, 0.25, 2, 'ai', NULL, true),
('a2566da0-43d0-4e5d-a14a-f9e4e28daa88', 'reading_comprehension', 'According to the passage, what have some cities done to increase recycling participation?', '8f0002b3-025b-4163-a195-b62d4c46d5cd', '[{"id": "c", "text": "Banned recycling entirely"}, {"id": "b", "text": "Increased fines for not recycling"}, {"id": "a", "text": "Stopped collecting waste altogether"}, {"id": "d", "text": "Offered financial incentives such as reduced waste collection fees"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את הפתרון שהוצע בפסקה.", "correct_reason": "הפסקה אומרת: ''some municipalities have started offering financial incentives, such as reduced waste collection fees''.", "options_analysis": ["הפוך גמור ממה שנאמר בפסקה", "לא נאמר בפסקה — אין אזכור לקנסות", "לא נאמר בפסקה כלל", "נכון! נאמר במפורש בפסקה"]}', 0.83, -1.0, 0.25, 2, 'ai', NULL, true),
('90428076-b269-4bd2-9015-c5ef3d3b1a35', 'reading_comprehension', 'What do officials report happens once residents understand the benefits of recycling incentives?', '8f0002b3-025b-4163-a195-b62d4c46d5cd', '[{"id": "b", "text": "Participation tends to increase"}, {"id": "a", "text": "Participation always decreases"}, {"id": "c", "text": "Cities stop offering incentives"}, {"id": "d", "text": "Residents refuse to recycle regardless"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את המשפט האחרון בפסקה.", "correct_reason": "הפסקה אומרת: ''participation tends to increase once residents understand both the environmental benefits and the personal financial savings involved''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "הפוך גמור ממה שנאמר בפסקה", "לא נאמר בפסקה כלל", "סותר את כל מטרת הפסקה שמתארת הצלחה של תמריצים"]}', 0.79, -1.0, 0.25, 2, 'ai', NULL, true);